// Guard node — request verification and the per-ticket daily cap. Runs once for
// all items and emits exactly one item whose `route` steers the rest of the
// workflow:
//   ok        — a real, saved column change of a known ticket
//   rejected  — everything else; the caller gets a bare 403
// The order of the checks is the point: the secret is tested first, so an
// unauthenticated request never touches the counter file.

// Valid board statuses, mirroring TASK_STATUS in js/core/constants.js. A value
// outside this list cannot come from the board and is treated as noise.
const VALID_STATUS = ['triage', 'todo', 'inprogress', 'awaitfeedback', 'done'];

// How many mails a single ticket may trigger per day. Someone who drags a card
// back and forth twenty times must not mail the requester twenty times.
const PER_TASK_LIMIT = 3;

// Own counter file on the n8n data volume, separate from the two quota files
// that already live there: `quota-state.json` belongs to Code a Cuisine and
// `join-quota-state.json` to the issue collector. Requires
// NODE_FUNCTION_ALLOW_BUILTIN to include `fs`.
const fs = require('fs');
const STATE_FILE = '/home/node/.n8n/join-notify-state.json';

/**
 * Wraps a routing decision into the single item the workflow expects.
 * @param {string} route - Either ok or rejected
 * @param {Object} extra - Fields merged into the item
 * @returns {Array<Object>} The n8n item list
 */
function emit(route, extra) {
  return [{ json: { route, reason: '', ...extra } }];
}

/**
 * Turns the request down. The reason never reaches the caller — the Respond
 * node answers a bare `rejected` — but it shows up in the execution log, which
 * is the only place where a failing call can be diagnosed.
 * @param {string} reason - Why the request was turned down
 * @returns {Array<Object>} The n8n item list
 */
function reject(reason) {
  return emit('rejected', { reason });
}

/**
 * Reads a request field as a trimmed string.
 * @param {any} value - The raw field of the request body
 * @returns {string} The trimmed value, empty when the field was not a string
 */
function readText(value) {
  return typeof value === 'string' ? value.trim() : '';
}

/**
 * Reads the counter file, returning a fresh state when it is missing.
 * @returns {Object} The notification state
 */
function readNotifyState() {
  try {
    return JSON.parse(fs.readFileSync(STATE_FILE, 'utf8'));
  } catch (error) {
    return { day: null, perTask: {} };
  }
}

/**
 * Persists the counter file.
 * @param {Object} state - The state to store
 * @returns {void}
 */
function writeNotifyState(state) {
  fs.writeFileSync(STATE_FILE, JSON.stringify(state));
}

/**
 * Starts a fresh counter on the first notification of a new UTC day. The
 * container runs on TZ=UTC, so the day rolls over at UTC midnight.
 * @param {Object} state - The state read from disk
 * @param {Date} now - The current time
 * @returns {Object} The state, reset when the day rolled over
 */
function resetWhenNewDay(state, now) {
  const day = now.toISOString().slice(0, 10);
  const sameDay = Boolean(state) && state.day === day;
  return { day, perTask: sameDay && state.perTask ? state.perTask : {} };
}

/**
 * Checks and reserves one mail slot for a ticket. The slot is taken before the
 * database is read, so a ticket whose creator turns out to be internal still
 * spends one — the cap limits calls, not successful mails.
 * @param {string} taskId - The ticket the notification belongs to
 * @returns {boolean} True when a slot was taken, false when the cap is reached
 */
function reserveSlot(taskId) {
  const state = resetWhenNewDay(readNotifyState(), new Date());
  const used = Number(state.perTask[taskId]) || 0;
  if (used >= PER_TASK_LIMIT) return false;
  state.perTask[taskId] = used + 1;
  writeNotifyState(state);
  return true;
}

// --- main -------------------------------------------------------------------
const request = $input.first().json;

// Fail loudly instead of rejecting every call: without the variable the secret
// would be an empty string and nothing would ever pass the guard, with no hint
// anywhere as to why. Requires N8N_BLOCK_ENV_ACCESS_IN_NODE=false.
const secret = String($env.JOIN_NOTIFY_SECRET || '');
if (secret === '') {
  throw new Error('JOIN_NOTIFY_SECRET is not set on the container - see docs/n8n-setup.md section 9.');
}

// Header names arrive in lower case, whatever the client sent.
const headers = request.headers || {};
if (String(headers['x-join-secret'] || '') !== secret) return reject('secret mismatch');

const body = request.body || {};
const taskId = readText(body.taskId);
const from = readText(body.from);
const to = readText(body.to);
if (taskId === '' || from === '' || to === '') return reject('taskId, from or to missing');
if (!VALID_STATUS.includes(from) || !VALID_STATUS.includes(to)) return reject('unknown status value');
if (from === to) return reject('status did not change');
if (!reserveSlot(taskId)) return reject('daily notification cap reached for ' + taskId);

return emit('ok', { taskId, from, to });

// Build mail — decides whether this column change is worth a mail and, if so,
// writes it. Runs once for all items and emits exactly one item:
//   ok       — `to`, `subject` and `text` are filled in
//   skipped  — no mail: the ticket has no external creator with an address
// The recipient comes from the record the previous node read out of the
// database, never from the request. See the note on `Fetch task`.

// Readable labels for the five board statuses. The raw values are how the
// database spells them, not how a stakeholder should read them.
const STATUS_LABELS = {
  triage: 'Triage',
  todo: 'To do',
  inprogress: 'In progress',
  awaitfeedback: 'Await feedback',
  done: 'Done',
};

const change = $('Guard: verify, throttle').first().json;

/**
 * Unwraps the answer of the task GET. n8n hands a JSON object through
 * unchanged but wraps a bare `null` body — an unknown ticket id — under `data`.
 * @param {any} response - The item of the HTTP node
 * @returns {Object} The task record, empty when the ticket does not exist
 */
function resolveTask(response) {
  const body = response && response.data !== undefined ? response.data : response;
  return body && typeof body === 'object' ? body : {};
}

/**
 * Wraps a routing decision into the single item the workflow expects.
 * @param {string} route - Either ok or skipped
 * @param {Object} extra - Fields merged into the item
 * @returns {Array<Object>} The n8n item list
 */
function emit(route, extra) {
  return [{ json: { route, to: '', subject: '', text: '', ...extra } }];
}

/**
 * Reads the creator address, but only for external requesters. Internal
 * members work on the board and see the change there; the Lastenheft asks for
 * a mail to the stakeholder who filed the request, nobody else.
 * @param {Object} task - The task record from the database
 * @returns {string} The address, empty when no mail should go out
 */
function resolveRecipient(task) {
  const creator = task.createdBy || {};
  if (creator.type !== 'extern') return '';
  return String(creator.email || '').trim();
}

/**
 * Turns a stored status value into something a reader understands.
 * @param {string} status - The raw status value
 * @returns {string} The label, falling back to the raw value
 */
function labelOf(status) {
  return STATUS_LABELS[status] || status;
}

/**
 * Salutation line, using the creator's name when the record carries one.
 * @param {Object} task - The task record from the database
 * @returns {string} The greeting
 */
function buildGreeting(task) {
  const name = String((task.createdBy || {}).name || '').trim();
  return name && name.indexOf('@') === -1 ? 'Hello ' + name + ',' : 'Hello,';
}

/**
 * The closing lines of every mail this workflow sends.
 * @returns {Array<string>} The signature lines
 */
function buildSignature() {
  return ['', 'Kind regards', 'The Join team'];
}

/**
 * The mail body: what moved, from where to where, and that no answer is due.
 * @param {Object} task - The task record from the database
 * @param {string} title - The ticket title
 * @returns {string} The plain text body
 */
function buildText(task, title) {
  return [
    buildGreeting(task),
    '',
    'your request has moved to another column on the Join board.',
    '',
    'Ticket: ' + title,
    'From:   ' + labelOf(change.from),
    'To:     ' + labelOf(change.to),
    '',
    'This is an automatic status update. You do not need to reply to it.',
  ]
    .concat(buildSignature())
    .join('\n');
}

// --- main -------------------------------------------------------------------
const task = resolveTask($input.first().json);
const recipient = resolveRecipient(task);
if (recipient === '') return emit('skipped', { reason: 'no external creator with an address' });

const title = String(task.title || change.taskId);

return emit('ok', {
  to: recipient,
  subject: '[JOIN] ' + title + ' - now in ' + labelOf(change.to),
  text: buildText(task, title),
});
